const owner='hsndm566', repo='hsndm.tech', branch='main';
// Each item: the file + the exact Opus/Claude commit that was truncated mid-file.
return [
  { json: { owner, repo, branch, filePath: 'dashboard.html', opusRef: '9f17a4c' } },
  { json: { owner, repo, branch, filePath: 'cv.html', opusRef: '1e1382b' } },
];

const meta = $('Loop Over Files').item.json;
function dec(resp){ const raw=(resp&&resp.content)||''; if((resp&&resp.encoding||'base64')==='base64'){ try { return Buffer.from(raw,'base64').toString('utf8'); } catch(e){ return raw; } } return raw; }
const seed = dec($('Fetch Opus Seed').item.json);
const live = dec($('Fetch Live File').item.json);

// --- Extract the known-good functional script bundle from the CURRENT live file ---
// Find the <script> block that carries the working integrations.
let liveScripts='';
const markerIdx = (function(){ const keys=['SHEET_ID','JULIE_ENDPOINT','SUBMIT_ENDPOINT']; let best=-1; for(const k of keys){ const i=live.indexOf(k); if(i!==-1 && (best===-1||i<best)) best=i; } return best; })();
if (markerIdx !== -1) {
  const scriptStart = live.lastIndexOf('<script', markerIdx);
  const htmlEnd = live.lastIndexOf('</html>');
  if (scriptStart !== -1 && htmlEnd !== -1) {
    liveScripts = live.substring(scriptStart, htmlEnd).replace(/<\/body>\s*$/,'').trim();
  }
}

// --- Tokens the finished file MUST contain (working endpoints + sheet id) ---
const preserve = [];
const urls = live.match(/https?:\/\/[^\s"'<>]+/g) || [];
for (const u of urls){ if (u.indexOf('app.n8n.cloud/webhook')!==-1 && preserve.indexOf(u)===-1) preserve.push(u); }
const sid = live.match(/SHEET_ID\s*[=:]\s*["']([^"']+)["']/);
if (sid) preserve.push(sid[1]);

const systemPrompt = 'You are completing an HTML file that a senior designer started and which was accidentally TRUNCATED mid-file. You will receive the PARTIAL file exactly as it was cut off. Reproduce the entire document and seamlessly CONTINUE from the exact truncation point to a complete, valid HTML page. Strictly preserve the design language, CSS custom properties, class names, color palette, spacing and visual style already established in the partial. Do NOT redesign, restart, summarize, or alter anything before the cut. Complete any unclosed tags, finish the current section, add the remaining sections implied by the existing structure/navigation, and properly close body and html. Output ONLY the full HTML document from <!DOCTYPE html> to the closing html tag. No markdown fences, no commentary.';
const userPrompt = 'Here is the truncated partial file for ' + meta.filePath + '. Continue and complete it:\n\n' + seed;

return [{ json: { owner: meta.owner, repo: meta.repo, branch: meta.branch, filePath: meta.filePath, seed, liveScripts, preserve, systemPrompt, userPrompt } }];

const d = $('Decode & Build Prompt').item.json;
const resp = $input.first().json;
let content='';
try { content = (resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || ''; } catch(e){ content=''; }
content = (content||'').trim();
if (content.indexOf('\u0060\u0060\u0060')===0){ content = content.replace(/^\u0060\u0060\u0060[a-zA-Z]*\n?/,'').replace(/\u0060\u0060\u0060\s*$/,'').trim(); }
const di = content.indexOf('<!DOCTYPE html>');
const hi = content.lastIndexOf('</html>');
if (di>0) content = content.substring(di).trim();
if (hi!==-1) content = content.substring(0, content.lastIndexOf('</html>')+7).trim();

// --- Guarantee integrations: re-inject known-good live scripts if any token missing ---
const preserve = d.preserve || [];
let missing = preserve.filter(t => content.indexOf(t)===-1);
if (missing.length && d.liveScripts) {
  const bodyCloseIdx = content.lastIndexOf('</body>');
  if (bodyCloseIdx !== -1) { content = content.slice(0,bodyCloseIdx) + '\n' + d.liveScripts + '\n' + content.slice(bodyCloseIdx); }
  else if (content.indexOf('</html>')!==-1) { content = content.replace('</html>', d.liveScripts + '\n</body>\n</html>'); }
  missing = preserve.filter(t => content.indexOf(t)===-1);
}

const startsOk = content.indexOf('<!DOCTYPE html>')===0;
const endsOk = content.slice(-7)==='</html>';
const bodyOpen = (content.match(/<body[\s>]/gi)||[]).length;
const bodyClose = (content.match(/<\/body>/gi)||[]).length;
const scriptOpen = (content.match(/<script[\s>]/gi)||[]).length;
const scriptClose = (content.match(/<\/script>/gi)||[]).length;
const structOk = startsOk && endsOk && bodyOpen>=1 && bodyOpen===bodyClose && scriptOpen>=1 && scriptOpen===scriptClose;
const isValid = structOk && missing.length===0 && content.length > 3000;
const reason = 'GROQ start='+startsOk+' end='+endsOk+' body='+bodyOpen+'/'+bodyClose+' script='+scriptOpen+'/'+scriptClose+' missing='+missing.length+' len='+content.length;
return [{ json: { owner:d.owner, repo:d.repo, branch:d.branch, filePath:d.filePath, finalHtml:content, isValid, reason, provider:'GROQ' } }];

